package com.securebiz.inventory.repository;

import com.securebiz.inventory.api.StockOperationDtos.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
import java.math.BigDecimal;import java.sql.ResultSet;import java.sql.SQLException;import java.util.*;

@Repository
public class StockOperationRepository {
 private final JdbcClient jdbc;public StockOperationRepository(JdbcClient jdbc){this.jdbc=jdbc;}
 public TransferResponse createTransfer(UUID id,String number,TransferRequest r,UUID actor){jdbc.sql("INSERT INTO stock_transfers(id,transfer_number,source_warehouse_id,destination_warehouse_id,reason,created_by) VALUES(:id,:n,:s,:d,:r,:a)").param("id",id).param("n",number).param("s",r.sourceWarehouseId()).param("d",r.destinationWarehouseId()).param("r",r.reason()).param("a",actor).update();for(var item:r.items())jdbc.sql("INSERT INTO stock_transfer_items(stock_transfer_id,product_variant_id,requested_quantity) VALUES(:t,:v,:q)").param("t",id).param("v",item.variantId()).param("q",item.quantity()).update();return transfer(id).orElseThrow();}
 public List<TransferResponse> transfers(int size,long offset){return jdbc.sql("SELECT * FROM stock_transfers ORDER BY created_at DESC LIMIT :size OFFSET :offset").param("size",size).param("offset",offset).query(this::mapTransfer).list();}
 public long countTransfers(){return jdbc.sql("SELECT count(*) FROM stock_transfers").query(Long.class).single();}
 public Optional<TransferResponse> transfer(UUID id){return jdbc.sql("SELECT * FROM stock_transfers WHERE id=:id").param("id",id).query(this::mapTransfer).optional();}
 public Optional<TransferLock> lockTransfer(UUID id){return jdbc.sql("SELECT id,source_warehouse_id,destination_warehouse_id,status,created_by FROM stock_transfers WHERE id=:id FOR UPDATE").param("id",id).query((r,n)->new TransferLock(r.getObject("id",UUID.class),r.getObject("source_warehouse_id",UUID.class),r.getObject("destination_warehouse_id",UUID.class),r.getString("status"),r.getObject("created_by",UUID.class))).optional();}
 public int transitionTransfer(UUID id,String from,String to,UUID actor){String actorColumn=switch(to){case"APPROVED"->"approved_by";case"DISPATCHED"->"dispatched_by";case"COMPLETED"->"received_by";default->null;};String timeColumn=switch(to){case"APPROVED"->"approved_at";case"DISPATCHED"->"dispatched_at";case"COMPLETED"->"received_at";default->null;};String extra=actorColumn==null?"":","+actorColumn+"=:actor,"+timeColumn+"=now()";return jdbc.sql("UPDATE stock_transfers SET status=:to,updated_at=now(),version=version+1"+extra+" WHERE id=:id AND status=:from").param("to",to).param("id",id).param("from",from).param("actor",actor).update();}
 public List<TransferLine> lockTransferLines(UUID transfer){return jdbc.sql("SELECT id,product_variant_id,requested_quantity,dispatched_quantity,received_quantity FROM stock_transfer_items WHERE stock_transfer_id=:id ORDER BY product_variant_id FOR UPDATE").param("id",transfer).query((r,n)->new TransferLine(r.getObject("id",UUID.class),r.getObject("product_variant_id",UUID.class),r.getBigDecimal("requested_quantity"),r.getBigDecimal("dispatched_quantity"),r.getBigDecimal("received_quantity"))).list();}
 public void markDispatched(UUID id,BigDecimal q){jdbc.sql("UPDATE stock_transfer_items SET dispatched_quantity=:q WHERE id=:id").param("q",q).param("id",id).update();}
 public void markReceived(UUID id,BigDecimal q){jdbc.sql("UPDATE stock_transfer_items SET received_quantity=:q WHERE id=:id").param("q",q).param("id",id).update();}
 public StocktakeResponse createStocktake(UUID id,String number,StocktakeRequest r,UUID actor){jdbc.sql("INSERT INTO stocktakes(id,stocktake_number,warehouse_id,status,reason,created_by) VALUES(:id,:n,:w,'COUNTING',:r,:a)").param("id",id).param("n",number).param("w",r.warehouseId()).param("r",r.reason()).param("a",actor).update();jdbc.sql("INSERT INTO stocktake_items(stocktake_id,product_variant_id,system_quantity) SELECT :id,product_variant_id,quantity FROM inventory WHERE warehouse_id=:w").param("id",id).param("w",r.warehouseId()).update();return stocktake(id).orElseThrow();}
 public List<StocktakeResponse> stocktakes(int size,long offset){return jdbc.sql("SELECT * FROM stocktakes ORDER BY created_at DESC LIMIT :size OFFSET :offset").param("size",size).param("offset",offset).query(this::mapStocktake).list();}
 public long countStocktakes(){return jdbc.sql("SELECT count(*) FROM stocktakes").query(Long.class).single();}
 public Optional<StocktakeResponse> stocktake(UUID id){return jdbc.sql("SELECT * FROM stocktakes WHERE id=:id").param("id",id).query(this::mapStocktake).optional();}
 public Optional<StocktakeLock> lockStocktake(UUID id){return jdbc.sql("SELECT id,warehouse_id,status,created_by FROM stocktakes WHERE id=:id FOR UPDATE").param("id",id).query((r,n)->new StocktakeLock(r.getObject("id",UUID.class),r.getObject("warehouse_id",UUID.class),r.getString("status"),r.getObject("created_by",UUID.class))).optional();}
 public void saveCounts(UUID stocktake,List<CountItemRequest> items){for(var item:items){int changed=jdbc.sql("UPDATE stocktake_items SET actual_quantity=:q,variance=:q-system_quantity WHERE id=:id AND stocktake_id=:s").param("q",item.actualQuantity()).param("id",item.itemId()).param("s",stocktake).update();if(changed==0)throw new IllegalArgumentException("Invalid stocktake item");}}
 public boolean allCounted(UUID id){return jdbc.sql("SELECT NOT EXISTS(SELECT 1 FROM stocktake_items WHERE stocktake_id=:id AND actual_quantity IS NULL)").param("id",id).query(Boolean.class).single();}
 public int transitionStocktake(UUID id,String from,String to,UUID actor){String approval="COMPLETED".equals(to)?",approved_by=:actor,approved_at=now()":"";return jdbc.sql("UPDATE stocktakes SET status=:to,updated_at=now(),version=version+1"+approval+" WHERE id=:id AND status=:from").param("to",to).param("actor",actor).param("id",id).param("from",from).update();}
 public List<StocktakeLine> lockStocktakeLines(UUID id){return jdbc.sql("SELECT id,product_variant_id,system_quantity,actual_quantity,variance FROM stocktake_items WHERE stocktake_id=:id ORDER BY product_variant_id FOR UPDATE").param("id",id).query((r,n)->new StocktakeLine(r.getObject("id",UUID.class),r.getObject("product_variant_id",UUID.class),r.getBigDecimal("system_quantity"),r.getBigDecimal("actual_quantity"),r.getBigDecimal("variance"))).list();}
 public void linkAdjustment(UUID item,UUID tx){jdbc.sql("UPDATE stocktake_items SET adjustment_transaction_id=:tx WHERE id=:id").param("tx",tx).param("id",item).update();}
 public void createStockHeader(UUID tx,String ref,UUID warehouse,String type,UUID actor,String source,UUID sourceId,String reason){jdbc.sql("INSERT INTO stock_transactions(id,reference,warehouse_id,type,actor_id,source_type,source_id,reason) VALUES(:id,:ref,:w,:type,:a,:source,:sourceId,:reason)").param("id",tx).param("ref",ref).param("w",warehouse).param("type",type).param("a",actor).param("source",source).param("sourceId",sourceId).param("reason",reason).update();}
 public void createStockItem(UUID tx,UUID variant,BigDecimal delta,BigDecimal before,BigDecimal after){jdbc.sql("INSERT INTO stock_transaction_items(stock_transaction_id,product_variant_id,quantity_delta,quantity_before,quantity_after) VALUES(:tx,:v,:d,:b,:a)").param("tx",tx).param("v",variant).param("d",delta).param("b",before).param("a",after).update();}
 private TransferResponse mapTransfer(ResultSet r,int n)throws SQLException{UUID id=r.getObject("id",UUID.class);return new TransferResponse(id,r.getString("transfer_number"),r.getObject("source_warehouse_id",UUID.class),r.getObject("destination_warehouse_id",UUID.class),r.getString("status"),r.getString("reason"),r.getObject("created_by",UUID.class),r.getLong("version"),r.getTimestamp("created_at").toInstant(),transferItems(id));}
 private List<TransferItemResponse> transferItems(UUID id){return jdbc.sql("SELECT i.id,i.product_variant_id,v.sku,i.requested_quantity,i.dispatched_quantity,i.received_quantity FROM stock_transfer_items i JOIN product_variants v ON v.id=i.product_variant_id WHERE i.stock_transfer_id=:id ORDER BY v.sku").param("id",id).query((r,n)->new TransferItemResponse(r.getObject("id",UUID.class),r.getObject("product_variant_id",UUID.class),r.getString("sku"),r.getBigDecimal("requested_quantity"),r.getBigDecimal("dispatched_quantity"),r.getBigDecimal("received_quantity"))).list();}
 private StocktakeResponse mapStocktake(ResultSet r,int n)throws SQLException{UUID id=r.getObject("id",UUID.class);return new StocktakeResponse(id,r.getString("stocktake_number"),r.getObject("warehouse_id",UUID.class),r.getString("status"),r.getString("reason"),r.getObject("created_by",UUID.class),r.getLong("version"),r.getTimestamp("created_at").toInstant(),stocktakeItems(id));}
 private List<StocktakeItemResponse> stocktakeItems(UUID id){return jdbc.sql("SELECT i.id,i.product_variant_id,v.sku,i.system_quantity,i.actual_quantity,i.variance FROM stocktake_items i JOIN product_variants v ON v.id=i.product_variant_id WHERE i.stocktake_id=:id ORDER BY v.sku").param("id",id).query((r,n)->new StocktakeItemResponse(r.getObject("id",UUID.class),r.getObject("product_variant_id",UUID.class),r.getString("sku"),r.getBigDecimal("system_quantity"),r.getBigDecimal("actual_quantity"),r.getBigDecimal("variance"))).list();}
 public record TransferLock(UUID id,UUID source,UUID destination,String status,UUID createdBy){} public record TransferLine(UUID id,UUID variant,BigDecimal requested,BigDecimal dispatched,BigDecimal received){} public record StocktakeLock(UUID id,UUID warehouse,String status,UUID createdBy){} public record StocktakeLine(UUID id,UUID variant,BigDecimal system,BigDecimal actual,BigDecimal variance){}
}
